    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.companyRevisionInfoEClass, source, new String[]{"documentation", "Use <companyRevisionInfo> , to generate information on document version within the respective company."});
        this.addAnnotation((ENamedElement)this.docRevisionEClass, source, new String[]{"documentation", "Use <docRevision> , to generate information on the corresponding document version."});
        this.addAnnotation((ENamedElement)this.getDocRevision_RevisionLabel(), source, new String[]{"documentation", "Use revisionLabel, to enter the version number of the document, or the document section to which administrative is applied.. The syntax is free and refers to the configuration management plan respectively the version management tool being used.\r\nTherefore it is still kept as String."});
        this.addAnnotation((ENamedElement)this.getDocRevision_RevisionLabelP1(), source, new String[]{"documentation", "Use revisionLabelP1, to enter the version number of the ** of the document, or the document section to which administrative is applied.. The syntax is free and refers to the configuration management plan respectively the version management tool being used. This element is used, if the document or document section is the result of a merge process in which two branches are merged in to one new revision."});
        this.addAnnotation((ENamedElement)this.getDocRevision_RevisionLabelP2(), source, new String[]{"documentation", "Use revisionLabelP1, to enter the version number of the ** of the document, or the document section to which administrative is applied.. The syntax is free and refers to the configuration management plan respectively the version management tool being used. This element is used, if the document or document section is the result of a merge process in which two branches are merged in to one new revision."});
        this.addAnnotation((ENamedElement)this.getDocRevision_State(), source, new String[]{"documentation", "<state> represents the current state of the current file according to the configuration management plan."});
        this.addAnnotation((ENamedElement)this.getDocRevision_IssuedBy(), source, new String[]{"documentation", "This element contains the name of the person who initiated the document revision. If the initiator cannot be referenced as <teamMember> in the current document his name can be given in this element."});
        this.addAnnotation((ENamedElement)this.getDocRevision_Date(), source, new String[]{"documentation", "This specifies the time, when the object in question was released"});
        this.addAnnotation((ENamedElement)this.getDocRevision_Modifications(), source, new String[]{"documentation", "Use <modification> to record what has changed in a document in comparison to its predecessor."});
        this.addAnnotation((ENamedElement)this.modificationEClass, source, new String[]{"documentation", "Use <modification> to record what has changed in a document in comparison to its predecessor."});
        this.addAnnotation((ENamedElement)this.getModification_Change(), source, new String[]{"documentation", "<change> is used to enter a modification text for a <modification> element. The element has the same contents and features as a normal Pararagraf element <p>."});
        this.addAnnotation((ENamedElement)this.getModification_Reason(), source, new String[]{"documentation", "Use <reason> to cite the reason for changes to the document version."});
        this.addAnnotation((ENamedElement)this.adminDataEClass, source, new String[]{"documentation", "<adminData> can be used to set administrative information for an element. This administration information is to be treated as metadata such as revision id or state of the file. There are basically four kinds of metadata\r\n\r\n* The language and/or used laguages.\r\n\r\n* Revision information covering e.g. revision number, state, release date, changes. Note that this information can be given in general as well as related to a particular company.\r\n\r\n* Document metadata specific for a company\r\n\r\n* Formatting controls that can affect layouts for example.\r\n\r\n* Revision information for the element."});
        this.addAnnotation((ENamedElement)this.getAdminData_Language(), source, new String[]{"documentation", "This attribute  specifies the master language of the document or the document fragment. The master language is the one in which the document is maintained and from which the other languages are derived from."});
        this.addAnnotation((ENamedElement)this.getAdminData_UsedLanguages(), source, new String[]{"documentation", "Use <usedLanguages> to enter all other languages, in addition to the document language, which are used an a document or a section of a document."});
        this.addAnnotation((ENamedElement)this.getAdminData_DocRevisions(), source, new String[]{"documentation", "Use <docRevision> , to generate information on the corresponding document version."});
        this.addAnnotation((ENamedElement)this.getAdminData_Sdgs(), source, new String[]{"documentation", "<sdg> (Special Data Group) is a backdoor used to handle elements that has not yet been defined in a DTD. The <sdg> is a containder for one or several <sd> that defines new elements and carries the information. Special Data should only be used moderately since all elements should be defined in the dtd. Thereby should SDG be considered as a temporary sollution when elements are missing. If a <sdgCaption> element is created along with a <shortName> it is possible to reference the <sdg> structure via a <xref>."});
    }

